/** Masters 1000 : une coupe par tournoi (drapeau du pays dans le médaillon) ; un nom inconnu garde la coupe « 1000 ». */
function cleMasters(nom) {
  const n = String(nom ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z]+/g, ' ').trim();
  if (/indian wells/.test(n)) return 'iw';
  if (/miami/.test(n)) return 'mi';
  if (/monte carlo|monaco/.test(n)) return 'mc';
  if (/madrid/.test(n)) return 'ma';
  if (/rome|roma/.test(n)) return 'ro';
  if (/canada|montreal|toronto/.test(n)) return 'ca';
  if (/cincinnati/.test(n)) return 'ci';
  if (/shanghai/.test(n)) return 'sh';
  if (/paris/.test(n)) return 'pa';
  return 'm1000';
}

/** Clé du dessin pour un tournoi : le nom reconnaît chaque Grand Chelem ; un nom inconnu reçoit un trophée doré neutre. */
export function cleTrophee(categorie, nom = null) {
  if (categorie === 'champion_saison') return 'champion';
  if (categorie === 'vice_champion_saison') return 'vice';
  if (categorie === 'masters_1000') return cleMasters(nom);
  if (categorie === 'atp_finals') return 'atpf';
  const n = String(nom ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z]+/g, ' ').trim();
  if (/australi/.test(n)) return 'ao';
  if (/roland|french/.test(n)) return 'rg';
  if (/wimbledon/.test(n)) return 'wi';
  if (/(^| )(us|u s) open( |$)|us open/.test(n)) return 'us';
  return 'gs';
}

/** Miniature de trophée (22 px par défaut). Le libellé accessible nomme le tournoi quand on le connaît. */
export function htmlTrophee(categorie, nom = null, tournoi = null, taille = 22) {
  const d = DESSINS[cleTrophee(categorie, nom)];
  const annee = tournoi?.annee ?? (tournoi?.date_debut ? Number(String(tournoi.date_debut).slice(0, 4)) : null);
  const libelle = nom ? (annee ? `${nom} ${annee}` : nom) : null;
  const titre = libelle ? `Trophée : ${libelle}` : `Trophée ${d.titre}`;
  const lien = nom && tournoi?.id != null ? ` data-tournoi="${echapper(tournoi.id)}"` : '';
  return `<svg class="trophee" viewBox="0 0 64 64" width="${taille}" height="${taille}" role="img" aria-label="${echapper(titre)}"${libelle ? ` data-nom="${echapper(libelle)}"` : ''}${lien}><title>${echapper(libelle ?? d.titre)}</title>${d.dessin}</svg>`;
}

/** Icône d'une « autre récompense » (Biggest win, grand fou, gagne-petit, sniper, contradicteur). '' si la clé est inconnue. `annee` optionnelle : ajoutée au libellé. */
export function htmlIconeRecompense(cle, taille = 40, annee = null) {
  const d = DESSINS[cle];
  if (!d) return '';
  const libelle = annee ? `${d.titre} ${annee}` : d.titre;
  return `<svg class="trophee icone-recompense" viewBox="0 0 64 64" width="${taille}" height="${taille}" role="img" aria-label="${echapper(libelle)}"><title>${echapper(libelle)}</title>${d.dessin}</svg>`;
}

